/**
 * ASTC Engine for Spritesheet Generator FNF
 * Decodes and encodes .astc textures client-side with WebAssembly.
 * Fully offline, no external server required.
 */
(function(global) {
    'use strict';

    const ASTC_WASM_B64 = '';

    // Orientación (verificada con texturas originales de FNF Android y pruebas de ida y vuelta):
    // - Los .astc del juego guardan la imagen DE PIE (fila 0 = arriba, igual que las coordenadas del XML).
    // - El codificador astcenc guarda el canvas tal cual (sin voltear).
    // - El decodificador WASM entrega las filas INVERTIDAS, por eso astcToCanvas voltea por defecto.
    const DECODER_OUTPUT_FLIPPED = true;

    let wasm = null;
    let cachedUint8Memory0 = null;
    let cachedInt32Memory0 = null;
    let WASM_VECTOR_LEN = 0;

    function getUint8Memory0() {
        if (cachedUint8Memory0 === null || cachedUint8Memory0.byteLength === 0) {
            cachedUint8Memory0 = new Uint8Array(wasm.memory.buffer);
        }
        return cachedUint8Memory0;
    }

    function getInt32Memory0() {
        if (cachedInt32Memory0 === null || cachedInt32Memory0.byteLength === 0) {
            cachedInt32Memory0 = new Int32Array(wasm.memory.buffer);
        }
        return cachedInt32Memory0;
    }

    function passArray8ToWasm0(arg, malloc) {
        const ptr = malloc(arg.length * 1, 1) >>> 0;
        getUint8Memory0().set(arg, ptr / 1);
        WASM_VECTOR_LEN = arg.length;
        return ptr;
    }

    function getArrayU8FromWasm0(ptr, len) {
        ptr = ptr >>> 0;
        return getUint8Memory0().subarray(ptr / 1, ptr / 1 + len);
    }

    function initDecoderSync() {
        if (wasm) return;
        const binStr = atob(ASTC_WASM_B64);
        const bytes = new Uint8Array(binStr.length);
        for (let i = 0; i < binStr.length; i++) {
            bytes[i] = binStr.charCodeAt(i);
        }
        const wasmModule = new WebAssembly.Module(bytes);
        const wasmInstance = new WebAssembly.Instance(wasmModule, {});
        wasm = wasmInstance.exports;
    }

    function astcDecodeRaw(data, width, height, blockWidth, blockHeight) {
        initDecoderSync();
        try {
            const retptr = wasm.__wbindgen_add_to_stack_pointer(-16);
            const ptr0 = passArray8ToWasm0(data, wasm.__wbindgen_malloc);
            const len0 = WASM_VECTOR_LEN;
            wasm.astcDecode(retptr, ptr0, len0, width, height, blockWidth, blockHeight);
            const r0 = getInt32Memory0()[retptr / 4 + 0];
            const r1 = getInt32Memory0()[retptr / 4 + 1];
            const v2 = getArrayU8FromWasm0(r0, r1).slice();
            wasm.__wbindgen_free(r0, r1 * 1);
            return v2;
        } finally {
            wasm.__wbindgen_add_to_stack_pointer(16);
        }
    }

    function parseHeader(bytes) {
        if (!bytes || bytes.length < 16) {
            throw new Error('El archivo es demasiado pequeño para ser un archivo .ASTC válido.');
        }
        if (bytes[0] !== 0x13 || bytes[1] !== 0xAB || bytes[2] !== 0xA1 || bytes[3] !== 0x5C) {
            throw new Error('Cabecera mágica inválida (se esperaba 0x13 0xAB 0xA1 0x5C). No es un archivo ASTC.');
        }
        const blockX = bytes[4];
        const blockY = bytes[5];
        const blockZ = bytes[6] || 1;
        const width = bytes[7] | (bytes[8] << 8) | (bytes[9] << 16);
        const height = bytes[10] | (bytes[11] << 8) | (bytes[12] << 16);
        const depth = bytes[13] | (bytes[14] << 8) | (bytes[15] << 16) || 1;

        if (width <= 0 || height <= 0 || blockX <= 0 || blockY <= 0) {
            throw new Error('Dimensiones o tamaño de bloque inválidos en el archivo ASTC.');
        }

        const bpp = (128 / (blockX * blockY)).toFixed(2);
        return {
            blockX,
            blockY,
            blockZ,
            width,
            height,
            depth,
            bpp,
            blockSizeName: blockX + 'x' + blockY,
            payloadOffset: 16
        };
    }

    function decodeAstc(fileBytes) {
        const header = parseHeader(fileBytes);
        const payload = fileBytes.subarray(16);
        const rgba = astcDecodeRaw(payload, header.width, header.height, header.blockX, header.blockY);
        return {
            header,
            rgba,
            width: header.width,
            height: header.height
        };
    }

    function flipCanvasVertical(srcCanvas) {
        const c = document.createElement('canvas');
        c.width = srcCanvas.width;
        c.height = srcCanvas.height;
        const ctx = c.getContext('2d');
        ctx.translate(0, c.height);
        ctx.scale(1, -1);
        ctx.drawImage(srcCanvas, 0, 0);
        return c;
    }

    function flipCanvasHorizontal(srcCanvas) {
        const c = document.createElement('canvas');
        c.width = srcCanvas.width;
        c.height = srcCanvas.height;
        const ctx = c.getContext('2d');
        ctx.translate(c.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(srcCanvas, 0, 0);
        return c;
    }

    function astcToCanvas(fileBytes, options = {}) {
        // Por defecto se compensa la salida invertida del decodificador para que la imagen quede de pie
        const flipY = options.flipY !== undefined ? options.flipY : DECODER_OUTPUT_FLIPPED;
        const decoded = decodeAstc(fileBytes);
        
        let canvas = document.createElement('canvas');
        canvas.width = decoded.width;
        canvas.height = decoded.height;
        const ctx = canvas.getContext('2d');
        const imgData = ctx.createImageData(decoded.width, decoded.height);
        imgData.data.set(decoded.rgba);
        ctx.putImageData(imgData, 0, 0);

        if (flipY) {
            canvas = flipCanvasVertical(canvas);
        }

        return {
            canvas,
            width: decoded.width,
            height: decoded.height,
            header: decoded.header,
            dataUrl: canvas.toDataURL('image/png')
        };
    }

    // Encoder module cache
    let encoderModulePromise = null;
    async function getEncoderModule() {
        if (!encoderModulePromise) {
            encoderModulePromise = (async () => {
                const getModuleFn = () => (
                    (typeof global.AstcEncoderModule === 'function' && global.AstcEncoderModule) ||
                    (typeof window !== 'undefined' && typeof window.AstcEncoderModule === 'function' && window.AstcEncoderModule) ||
                    (typeof globalThis !== 'undefined' && typeof globalThis.AstcEncoderModule === 'function' && globalThis.AstcEncoderModule)
                );

                let moduleFn = getModuleFn();
                if (!moduleFn) {
                    throw new Error('AstcEncoderModule no está cargado. Asegúrate de incluir js/astcenc.js.');
                }

                const moduleOpts = {
                    locateFile: (p) => 'js/' + p
                };

                // Si está disponible el binario base64 offline, úsalo directamente para evitar errores de CORS en file:///
                const b64Data = (typeof global.ASTCENC_WASM_B64 === 'string' && global.ASTCENC_WASM_B64) ||
                                (typeof window !== 'undefined' && typeof window.ASTCENC_WASM_B64 === 'string' && window.ASTCENC_WASM_B64) ||
                                (typeof globalThis !== 'undefined' && typeof globalThis.ASTCENC_WASM_B64 === 'string' && globalThis.ASTCENC_WASM_B64);

                if (b64Data) {
                    try {
                        const binStr = atob(b64Data);
                        const binLen = binStr.length;
                        const u8 = new Uint8Array(binLen);
                        for (let i = 0; i < binLen; i++) {
                            u8[i] = binStr.charCodeAt(i);
                        }
                        moduleOpts.wasmBinary = u8.buffer;
                    } catch (e) {
                        console.warn('No se pudo decodificar ASTCENC_WASM_B64, usando locateFile:', e);
                    }
                }

                const mod = await moduleFn(moduleOpts);
                return mod;
            })();
        }
        return encoderModulePromise;
    }

    /**
     * Purificador Inteligente Anti-Halos y Limpiador de Fondos Frame por Frame.
     * Elimina por completo los halos morados y blancos dejados por Flash/Photoshop
     * detectando colores de escenario, umbralizando residuos y aplicando sangrado de color activo.
     */
    function purifyCanvas(canvas, options = {}) {
        const mode = options.mode || 'framebyframe';
        const xmlFrames = options.xmlFrames || (options.xmlData && options.xmlData.frames) || null;
        const width = canvas.width;
        const height = canvas.height;
        const ctx = canvas.getContext('2d');
        const imgData = ctx.getImageData(0, 0, width, height);
        const data = imgData.data;
        const totalPixels = width * height;

        // Umbrales según el modo seleccionado
        let alphaThreshold = 8;
        let chromaTolerance = 65;
        let bleedPasses = 4;

        if (mode === 'normal') {
            alphaThreshold = 6;
            bleedPasses = 3;
            chromaTolerance = 50;
        } else if (mode === 'framebyframe') {
            alphaThreshold = 18; // Purgar feathering tenue y bordes
            bleedPasses = 5;
            chromaTolerance = 80;
        } else if (mode === 'advanced') {
            alphaThreshold = 26; // Ultra-purificación para eliminar auras y cajas densas
            bleedPasses = 6;
            chromaTolerance = 95;
        }

        // 1. Detección Inteligente del Color de Escenario / Fondo (Flash Stage Chroma)
        let sampleR = 0, sampleG = 0, sampleB = 0, sampleCount = 0;
        let whiteCount = 0, purpleCount = 0;

        // Muestrear píxeles de bajo alpha (halo / antialiasing de escenario) y bordes de la imagen
        const step = Math.max(1, Math.floor(data.length / (4 * 2500)));
        for (let i = 0; i < data.length; i += step * 4) {
            const a = data[i + 3];
            if (a > 0 && a <= 65) {
                const r = data[i], g = data[i + 1], b = data[i + 2];
                sampleR += r;
                sampleG += g;
                sampleB += b;
                sampleCount++;
                if (r > 200 && g > 200 && b > 200) whiteCount++;
                if (r > 60 && b > 80 && g < Math.max(r, b)) purpleCount++;
            }
        }

        const bgR = sampleCount > 0 ? Math.round(sampleR / sampleCount) : 255;
        const bgG = sampleCount > 0 ? Math.round(sampleG / sampleCount) : 255;
        const bgB = sampleCount > 0 ? Math.round(sampleB / sampleCount) : 255;

        // 2. Si hay XML, marcar máscara de área útil y purgar todo lo que esté fuera de los fotogramas
        let inFrameMask = null;
        if (xmlFrames && Array.isArray(xmlFrames) && xmlFrames.length > 0) {
            inFrameMask = new Uint8Array(totalPixels);
            for (let f of xmlFrames) {
                const fx = Math.max(0, Math.min(width - 1, f.x));
                const fy = Math.max(0, Math.min(height - 1, f.y));
                const fw = Math.min(width - fx, Math.max(0, f.w));
                const fh = Math.min(height - fy, Math.max(0, f.h));

                for (let y = fy; y < fy + fh; y++) {
                    const row = y * width;
                    for (let x = fx; x < fx + fw; x++) {
                        inFrameMask[row + x] = 1;
                    }
                }
            }
        }

        // 3. Purificación: eliminar polvo, feathering y color de escenario coincidente
        const isOpaque = new Uint8Array(totalPixels);
        const rCopy = new Uint8Array(totalPixels);
        const gCopy = new Uint8Array(totalPixels);
        const bCopy = new Uint8Array(totalPixels);

        // Umbrales agresivos para erradicar al 100% halos morados y blancos
        let hardAlphaCutoff = 35;
        let stageAlphaCutoff = 140;
        if (mode === 'normal') {
            hardAlphaCutoff = 25;
            stageAlphaCutoff = 100;
        } else if (mode === 'framebyframe') {
            hardAlphaCutoff = 45;
            stageAlphaCutoff = 160;
        } else if (mode === 'advanced') {
            hardAlphaCutoff = 60;
            stageAlphaCutoff = 190;
        }

        for (let i = 0, p = 0; i < data.length; i += 4, p++) {
            // Si hay XML y el píxel está fuera de TODOS los frames, purgar a 0 absoluto inmediatamente
            if (inFrameMask && inFrameMask[p] === 0) {
                data[i] = 0;
                data[i + 1] = 0;
                data[i + 2] = 0;
                data[i + 3] = 0;
                isOpaque[p] = 0;
                continue;
            }

            const a = data[i + 3];
            if (a === 0) {
                isOpaque[p] = 0;
                continue;
            }

            const r = data[i];
            const g = data[i + 1];
            const b = data[i + 2];

            // Distancia de color al fondo de escenario detectado
            const distBg = sampleCount > 0 ? Math.sqrt((r - bgR) ** 2 + (g - bgG) ** 2 + (b - bgB) ** 2) : 999;
            // Distancia a blanco puro / gris Flash (#FFFFFF / #E5E5E5)
            const distWhite = Math.sqrt((r - 255) ** 2 + (g - 255) ** 2 + (b - 255) ** 2);
            // Distancia a morado/magenta típico de escenario FNF / Flash (#7A2B9E / #6D1F88 / #260a3a)
            const distPurple = Math.sqrt((r - 122) ** 2 + (g - 43) ** 2 + (b - 158) ** 2);
            const distPurpleDark = Math.sqrt((r - 38) ** 2 + (g - 10) ** 2 + (b - 58) ** 2);
            const isPurpleTone = (r > 30 && b > 50 && g < Math.max(r, b) * 0.78);
            const isWhiteOrGrey = (r > 160 && g > 160 && b > 160 && Math.abs(r - g) < 30 && Math.abs(g - b) < 30);

            let isResidue = false;
            if (a <= hardAlphaCutoff) {
                isResidue = true;
            } else if (a <= stageAlphaCutoff && (distBg <= chromaTolerance || distWhite <= 95 || distPurple <= 110 || distPurpleDark <= 85 || isPurpleTone || isWhiteOrGrey)) {
                isResidue = true;
            } else if (mode === 'advanced' && a <= 200 && (distWhite <= 85 || distPurple <= 95 || isPurpleTone || (distBg <= chromaTolerance && sampleCount > 10))) {
                isResidue = true;
            }

            if (isResidue) {
                data[i] = 0;
                data[i + 1] = 0;
                data[i + 2] = 0;
                data[i + 3] = 0;
                isOpaque[p] = 0;
            } else {
                // Solo marcar como opaco si es un píxel con opacidad sólida real
                if (a >= 210) {
                    isOpaque[p] = 1;
                    rCopy[p] = r;
                    gCopy[p] = g;
                    bCopy[p] = b;
                } else {
                    isOpaque[p] = 0; // Píxel semi-transparente de borde (se de-fringeará y no contaminará el sangrado)
                }
            }
        }

        // 4. De-fringing Profundo: reemplazar cualquier tono residual en bordes semi-transparentes
        // con el color sólido del personaje (evita 100% que los bordes semi-transparentes tengan morado o blanco)
        for (let y = 0; y < height; y++) {
            const row = y * width;
            for (let x = 0; x < width; x++) {
                const p = row + x;
                const p4 = p * 4;
                const a = data[p4 + 3];
                if (a > 0 && a < 210) {
                    let bestR = data[p4], bestG = data[p4 + 1], bestB = data[p4 + 2], found = false;
                    const searchRadius = (mode === 'advanced') ? 5 : 4;

                    // Tomar el color del píxel opaco MÁS CERCANO (antes se tomaba el primero encontrado
                    // desde arriba a la izquierda, lo que pintaba bordes con colores de otra zona:
                    // puntos blancos/naranjas alrededor del contorno)
                    let bestDist = Infinity;
                    for (let dy = -searchRadius; dy <= searchRadius; dy++) {
                        const ny = y + dy;
                        if (ny < 0 || ny >= height) continue;
                        const nRow = ny * width;
                        for (let dx = -searchRadius; dx <= searchRadius; dx++) {
                            const nx = x + dx;
                            if (nx < 0 || nx >= width) continue;
                            const np = nRow + nx;
                            const dist = dx * dx + dy * dy;
                            if (isOpaque[np] === 1 && dist < bestDist) {
                                bestDist = dist;
                                bestR = rCopy[np];
                                bestG = gCopy[np];
                                bestB = bCopy[np];
                                found = true;
                            }
                        }
                    }

                    if (found) {
                        data[p4] = bestR;
                        data[p4 + 1] = bestG;
                        data[p4 + 2] = bestB;
                        rCopy[p] = bestR;
                        gCopy[p] = bestG;
                        bCopy[p] = bestB;
                    } else if (a < 200) {
                        // Si es un píxel aislado semi-transparente sin color sólido de personaje cercano, es residuo de escenario
                        data[p4] = 0;
                        data[p4 + 1] = 0;
                        data[p4 + 2] = 0;
                        data[p4 + 3] = 0;
                    }
                }
            }
        }

        // 5. Sangrado de color activo (Alpha Dilation BFS)
        // Extiende ÚNICAMENTE colores limpios de personajes hacia los píxeles transparentes adyacentes
        let frontier = [];
        for (let y = 0; y < height; y++) {
            const row = y * width;
            for (let x = 0; x < width; x++) {
                const p = row + x;
                if (data[p * 4 + 3] === 0) {
                    if ((x > 0 && isOpaque[p - 1] === 1) ||
                        (x < width - 1 && isOpaque[p + 1] === 1) ||
                        (y > 0 && isOpaque[p - width] === 1) ||
                        (y < height - 1 && isOpaque[p + width] === 1)) {
                        frontier.push(p);
                    }
                }
            }
        }

        const dilatedPixels = new Uint8Array(totalPixels);
        for (let pass = 0; pass < bleedPasses && frontier.length > 0; pass++) {
            const nextFrontier = [];

            for (let k = 0; k < frontier.length; k++) {
                const p = frontier[k];
                const x = p % width;
                const y = (p / width) | 0;

                let sumR = 0, sumG = 0, sumB = 0, count = 0;
                const yStart = Math.max(0, y - 1);
                const yEnd = Math.min(height - 1, y + 1);
                const xStart = Math.max(0, x - 1);
                const xEnd = Math.min(width - 1, x + 1);

                for (let ny = yStart; ny <= yEnd; ny++) {
                    const nRow = ny * width;
                    for (let nx = xStart; nx <= xEnd; nx++) {
                        if (nx === x && ny === y) continue;
                        const np = nRow + nx;
                        if (isOpaque[np] === 1) {
                            sumR += rCopy[np];
                            sumG += gCopy[np];
                            sumB += bCopy[np];
                            count++;
                        }
                    }
                }

                if (count > 0) {
                    const newR = (sumR / count) | 0;
                    const newG = (sumG / count) | 0;
                    const newB = (sumB / count) | 0;

                    rCopy[p] = newR;
                    gCopy[p] = newG;
                    bCopy[p] = newB;

                    const p4 = p * 4;
                    data[p4] = newR;
                    data[p4 + 1] = newG;
                    data[p4 + 2] = newB;
                    // Mantener alpha en 0 (completamente transparente pero con color del personaje para ASTC)
                    data[p4 + 3] = 0;

                    dilatedPixels[p] = 1;
                }
            }

            for (let k = 0; k < frontier.length; k++) {
                isOpaque[frontier[k]] = 1;
            }

            if (pass < bleedPasses - 1) {
                for (let k = 0; k < frontier.length; k++) {
                    const p = frontier[k];
                    const x = p % width;
                    const y = (p / width) | 0;

                    const neighbors = [];
                    if (x > 0) neighbors.push(p - 1);
                    if (x < width - 1) neighbors.push(p + 1);
                    if (y > 0) neighbors.push(p - width);
                    if (y < height - 1) neighbors.push(p + width);

                    for (let n = 0; n < neighbors.length; n++) {
                        const np = neighbors[n];
                        if (isOpaque[np] === 0 && data[np * 4 + 3] === 0) {
                            isOpaque[np] = 2;
                            nextFrontier.push(np);
                        }
                    }
                }

                for (let n = 0; n < nextFrontier.length; n++) {
                    isOpaque[nextFrontier[n]] = 0;
                }
                frontier = nextFrontier;
            }
        }

        // 6. Fondo distante a (0, 0, 0, 0) absoluto para bloques constantes en ASTC
        for (let i = 0, p = 0; i < data.length; i += 4, p++) {
            if (data[i + 3] === 0 && dilatedPixels[p] === 0) {
                data[i] = 0;
                data[i + 1] = 0;
                data[i + 2] = 0;
            }
        }

        ctx.putImageData(imgData, 0, 0);
        return { bgR, bgG, bgB, alphaThreshold, bleedPasses };
    }

    /**
     * Auditoría de Textura ASTC decodificada:
     * Inspecciona los píxeles decodificados para comprobar si quedaron residuos o halos.
     */
    function auditTexture(canvasOrObj, xmlFrames) {
        const canvas = (canvasOrObj && canvasOrObj.canvas) ? canvasOrObj.canvas : canvasOrObj;
        if (!canvas || typeof canvas.getContext !== 'function') {
            return {
                hasFlaws: false,
                residualCount: 0,
                suspiciousHalos: 0,
                totalEvaluated: 0
            };
        }
        const width = canvas.width;
        const height = canvas.height;
        const ctx = canvas.getContext('2d');
        const imgData = ctx.getImageData(0, 0, width, height);
        const data = imgData.data;

        let residualCount = 0;
        let suspiciousHalos = 0;

        for (let i = 0; i < data.length; i += 4) {
            const a = data[i + 3];
            if (a > 0 && a <= 25) {
                residualCount++;
            } else if (a > 25 && a <= 60) {
                const r = data[i], g = data[i + 1], b = data[i + 2];
                if ((r > 230 && g > 230 && b > 230) || (r > 100 && b > 140 && g < 80)) {
                    suspiciousHalos++;
                }
            }
        }

        const hasFlaws = (residualCount > 400 || suspiciousHalos > 120);
        return {
            hasFlaws,
            residualCount,
            suspiciousHalos,
            totalEvaluated: width * height
        };
    }

    function applyColorBleedAndCleanAlpha(canvas, passes = 5) {
        return purifyCanvas(canvas, { mode: 'framebyframe', bleedPasses: passes });
    }

    /**
     * Sangrado de color NO destructivo: no borra ni modifica ningún píxel visible.
     * Solo rellena el RGB de los píxeles 100% transparentes cercanos al contenido con el color
     * del borde vecino (para que ASTC no mezcle colores basura en los bordes) y deja el resto en (0,0,0,0).
     */
    function bleedTransparentPixels(canvas, passes = 4) {
        const width = canvas.width;
        const height = canvas.height;
        const ctx = canvas.getContext('2d');
        const imgData = ctx.getImageData(0, 0, width, height);
        const data = imgData.data;
        const total = width * height;
        const filled = new Uint8Array(total);
        for (let p = 0; p < total; p++) {
            if (data[p * 4 + 3] > 0) filled[p] = 1;
        }

        let frontier = [];
        for (let y = 0; y < height; y++) {
            for (let x = 0; x < width; x++) {
                const p = y * width + x;
                if (filled[p]) continue;
                if ((x > 0 && filled[p - 1]) || (x < width - 1 && filled[p + 1]) ||
                    (y > 0 && filled[p - width]) || (y < height - 1 && filled[p + width])) {
                    frontier.push(p);
                }
            }
        }

        for (let pass = 0; pass < passes && frontier.length > 0; pass++) {
            const done = [];
            for (const p of frontier) {
                if (filled[p]) continue;
                const x = p % width;
                const y = (p / width) | 0;
                let r = 0, g = 0, b = 0, n = 0;
                for (let ny = Math.max(0, y - 1); ny <= Math.min(height - 1, y + 1); ny++) {
                    for (let nx = Math.max(0, x - 1); nx <= Math.min(width - 1, x + 1); nx++) {
                        const np = ny * width + nx;
                        if (filled[np]) {
                            r += data[np * 4];
                            g += data[np * 4 + 1];
                            b += data[np * 4 + 2];
                            n++;
                        }
                    }
                }
                if (n > 0) {
                    data[p * 4] = (r / n) | 0;
                    data[p * 4 + 1] = (g / n) | 0;
                    data[p * 4 + 2] = (b / n) | 0;
                    done.push(p);
                }
            }
            const next = [];
            for (const p of done) filled[p] = 1;
            for (const p of done) {
                const x = p % width;
                if (x > 0 && !filled[p - 1]) next.push(p - 1);
                if (x < width - 1 && !filled[p + 1]) next.push(p + 1);
                if (p >= width && !filled[p - width]) next.push(p - width);
                if (p + width < total && !filled[p + width]) next.push(p + width);
            }
            frontier = next;
        }

        // Fondo lejano a (0,0,0,0) absoluto para que ASTC genere bloques constantes
        for (let p = 0; p < total; p++) {
            if (!filled[p]) {
                data[p * 4] = 0;
                data[p * 4 + 1] = 0;
                data[p * 4 + 2] = 0;
            }
        }
        ctx.putImageData(imgData, 0, 0);
        return { mode: 'safe', bleedPasses: passes };
    }

    function alignUp(v, a) {
        return Math.ceil(v / a) * a;
    }

    /**
     * Empaquetador de atlas para ASTC.
     * - Elimina recortes repetidos (mismo x, y, ancho, alto en el XML).
     * - Quita todo el espacio vacío del atlas original.
     * - Coloca cada recorte alineado a la rejilla de bloques ASTC con separación,
     *   para que ningún bloque mezcle píxeles de dos fotogramas distintos.
     * rects: [{ x, y, w, h }] en coordenadas del PNG original.
     */
    function packAtlas(rects, options = {}) {
        const scale = options.scale || 1;
        const bx = options.blockX || 6;
        const by = options.blockY || 6;
        const pad = options.padding !== undefined ? options.padding : 2;

        const unique = new Map();
        for (const r of rects) {
            const key = `${r.x},${r.y},${r.w},${r.h}`;
            if (!unique.has(key) && r.w > 0 && r.h > 0) {
                unique.set(key, {
                    key,
                    sx: r.x, sy: r.y, sw: r.w, sh: r.h,
                    pw: Math.max(1, Math.round(r.w * scale)),
                    ph: Math.max(1, Math.round(r.h * scale))
                });
            }
        }

        const items = [...unique.values()].sort((a, b) => b.ph - a.ph || b.pw - a.pw);
        let area = 0;
        let maxItemW = 0;
        for (const it of items) {
            area += alignUp(it.pw + pad, bx) * alignUp(it.ph + pad, by);
            maxItemW = Math.max(maxItemW, alignUp(it.pw + pad, bx));
        }
        const shelfW = Math.max(maxItemW, alignUp(Math.ceil(Math.sqrt(area * 1.05)), bx));

        let cx = 0, cy = 0, shelfH = 0, usedW = 0;
        for (const it of items) {
            const cellW = alignUp(it.pw + pad, bx);
            const cellH = alignUp(it.ph + pad, by);
            if (cx > 0 && cx + cellW > shelfW) {
                cx = 0;
                cy += shelfH;
                shelfH = 0;
            }
            it.px = cx;
            it.py = cy;
            cx += cellW;
            shelfH = Math.max(shelfH, cellH);
            usedW = Math.max(usedW, cx);
        }

        return {
            width: Math.max(bx, usedW),
            height: Math.max(by, cy + shelfH),
            items,
            map: unique,
            uniqueCount: items.length
        };
    }

    // Dibuja cada recorte del PNG original en su nueva posición del atlas empaquetado (escalado si aplica)
    function renderPackedAtlas(image, pack) {
        const c = document.createElement('canvas');
        c.width = pack.width;
        c.height = pack.height;
        const ctx = c.getContext('2d');
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        for (const it of pack.items) {
            ctx.drawImage(image, it.sx, it.sy, it.sw, it.sh, it.px, it.py, it.pw, it.ph);
        }
        return c;
    }

    // Decodifica un payload ASTC (sin cabecera) a RGBA con la fila 0 arriba
    function decodePayloadUpright(payload, width, height, bx, by) {
        const raw = astcDecodeRaw(payload, width, height, bx, by);
        if (!DECODER_OUTPUT_FLIPPED) return raw;
        const out = new Uint8Array(raw.length);
        const row = width * 4;
        for (let y = 0; y < height; y++) {
            out.set(raw.subarray((height - 1 - y) * row, (height - y) * row), y * row);
        }
        return out;
    }

    // Error visual de un bloque: los residuos sobre zonas que deben ser transparentes
    // cuentan mucho más, porque en el juego se ven como manchas alrededor del personaje.
    function blockError(src, dec, width, x0, y0, bx, by, srcStride, srcX, srcY) {
        let e = 0;
        for (let j = 0; j < by; j++) {
            for (let i = 0; i < bx; i++) {
                const s = ((srcY + j) * srcStride + (srcX + i)) * 4;
                const d = ((y0 + j) * width + (x0 + i)) * 4;
                const sa = src[s + 3], da = dec[d + 3];
                const ea = sa - da;
                if (sa === 0) {
                    e += da * da * 8;
                } else {
                    const dr = src[s] - dec[d], dg = src[s + 1] - dec[d + 1], db = src[s + 2] - dec[d + 2];
                    e += ea * ea * 2 + (dr * dr + dg * dg + db * db) * (sa / 255) / 3;
                }
            }
        }
        return e;
    }

    /**
     * Reparación de bordes bloque por bloque.
     * Cada bloque ASTC se decodifica de forma independiente, así que se pueden recomprimir
     * solo los bloques del borde que dejaron residuos (alfa fantasma alrededor del personaje),
     * probar varias variantes con calidad máxima y quedarse con la que menos error visual deja.
     */
    function repairEdgeBlocks(payload, src, width, height, bx, by, encoder, baseConfig, swizzle) {
        const t0 = performance.now();
        const nbx = Math.ceil(width / bx);
        const nby = Math.ceil(height / by);
        const dec = decodePayloadUpright(payload, width, height, bx, by);

        // 1. Localizar bloques con residuos o bordes dañados
        const bad = [];
        let leakBefore = 0;
        for (let gy = 0; gy < nby; gy++) {
            for (let gx = 0; gx < nbx; gx++) {
                let leaks = 0, holes = 0, aerr = 0, n = 0;
                for (let j = 0; j < by; j++) {
                    const y = gy * by + j;
                    if (y >= height) break;
                    for (let i = 0; i < bx; i++) {
                        const x = gx * bx + i;
                        if (x >= width) break;
                        const k = (y * width + x) * 4;
                        const sa = src[k + 3], da = dec[k + 3];
                        if (sa === 0 && da >= 6) leaks++;
                        else if (sa === 255 && da < 230) holes++;
                        aerr += Math.abs(sa - da);
                        n++;
                    }
                }
                leakBefore += leaks;
                if (leaks > 0 || holes > 0 || aerr / Math.max(1, n) > 6) bad.push(gy * nbx + gx);
            }
        }
        if (bad.length === 0) {
            return { payload, report: { revisados: 0, reparados: 0, fugasAntes: 0, fugasDespues: 0, seg: 0 } };
        }

        const exhaustive = Object.assign({}, baseConfig, { quality: 100 });
        const out = new Uint8Array(payload);
        let curDec = dec;

        // Recomprime una lista de bloques con varias variantes de entrada (empaquetados en un mosaico,
        // una sola llamada al codificador por variante) y se queda, bloque a bloque, con la opción
        // de menor error visual frente a la entrada real (incluida la que ya había).
        const tryVariants = (blocks, transforms) => {
            const cols = Math.ceil(Math.sqrt(blocks.length));
            const rows = Math.ceil(blocks.length / cols);
            const tw = cols * bx, th = rows * by;
            const candidates = transforms.map(transform => {
                const t = new Uint8Array(tw * th * 4);
                blocks.forEach((b, k) => {
                    const gx = b % nbx, gy = (b / nbx) | 0;
                    const tx = (k % cols) * bx, ty = ((k / cols) | 0) * by;
                    for (let j = 0; j < by; j++) {
                        const y = Math.min(height - 1, gy * by + j);
                        for (let i = 0; i < bx; i++) {
                            const x = Math.min(width - 1, gx * bx + i);
                            const s = (y * width + x) * 4, d = ((ty + j) * tw + (tx + i)) * 4;
                            t[d] = src[s]; t[d + 1] = src[s + 1]; t[d + 2] = src[s + 2];
                            t[d + 3] = transform ? transform(src[s + 3]) : src[s + 3];
                        }
                    }
                });
                const p = new Uint8Array(encoder.compressImage({ dimX: tw, dimY: th, dimZ: 1, dataType: 0, data: t }, exhaustive, swizzle, 1));
                return { payload: p, dec: decodePayloadUpright(p, tw, th, bx, by) };
            });
            let changed = 0;
            blocks.forEach((b, k) => {
                const gx = b % nbx, gy = (b / nbx) | 0;
                const tx = (k % cols) * bx, ty = ((k / cols) | 0) * by;
                const vw = Math.min(bx, width - gx * bx), vh = Math.min(by, height - gy * by);
                let best = blockError(src, curDec, width, gx * bx, gy * by, vw, vh, width, gx * bx, gy * by);
                let bestCand = -1;
                candidates.forEach((c, ci) => {
                    const e = blockError(src, c.dec, tw, tx, ty, vw, vh, width, gx * bx, gy * by);
                    if (e < best) { best = e; bestCand = ci; }
                });
                if (bestCand >= 0) {
                    out.set(candidates[bestCand].payload.subarray(k * 16, k * 16 + 16), b * 16);
                    changed++;
                }
            });
            curDec = decodePayloadUpright(out, width, height, bx, by);
            return changed;
        };

        // Etapa 1: misma entrada con calidad máxima (como "astcenc -exhaustive") en todos los bloques malos
        let repaired = tryVariants(bad, [null]);

        // Etapa 2: solo los bloques que siguen con residuos prueban un borde más definido
        const stillBad = bad.filter(b => {
            const gx = b % nbx, gy = (b / nbx) | 0;
            for (let j = 0; j < by; j++) {
                const y = gy * by + j;
                if (y >= height) break;
                for (let i = 0; i < bx; i++) {
                    const x = gx * bx + i;
                    if (x >= width) break;
                    const k = (y * width + x) * 4;
                    if (src[k + 3] === 0 && curDec[k + 3] >= 6) return true;
                }
            }
            return false;
        });
        if (stillBad.length > 0) {
            repaired += tryVariants(stillBad, [
                a => (a < 96 ? 0 : a >= 200 ? 255 : Math.round((a - 96) * 255 / 104)),   // borde más definido
                a => (a < 128 ? 0 : a >= 176 ? 255 : Math.round((a - 128) * 255 / 48))   // borde muy definido
            ]);
        }

        // Medir el resultado final
        let leakAfter = 0;
        for (let k = 0; k < src.length; k += 4) {
            if (src[k + 3] === 0 && curDec[k + 3] >= 6) leakAfter++;
        }
        return {
            payload: out,
            report: {
                revisados: bad.length,
                reparados: repaired,
                fugasAntes: leakBefore,
                fugasDespues: leakAfter,
                seg: +((performance.now() - t0) / 1000).toFixed(1)
            }
        };
    }

    async function encodeCanvasToAstc(canvas, options = {}) {
        const blockX = options.blockX || 6;
        const blockY = options.blockY || 6;
        // Por defecto: fiel al original (como astcenc), sin borrar ni recolorear píxeles del dibujo
        const mode = options.mode || 'normal';
        let qualityName = (options.quality || '').toLowerCase();
        if (!qualityName) {
            if (mode === 'normal' || mode === 'safe') qualityName = 'thorough';
            else if (mode === 'framebyframe') qualityName = 'thorough';
            else if (mode === 'advanced') qualityName = 'exhaustive';
            else qualityName = 'thorough';
        }

        // El canvas de entrada es la imagen DE PIE y el juego la espera igual: no se voltea
        const flipY = options.flipY !== undefined ? options.flipY : false;
        let quality = 60;
        if (qualityName === 'fastest') quality = 0;
        else if (qualityName === 'fast') quality = 25;
        else if (qualityName === 'medium') quality = 60;
        else if (qualityName === 'thorough') quality = 95;
        else if (qualityName === 'exhaustive') quality = 100;

        // Crear lienzo independiente para no modificar el original
        const sourceCanvas = document.createElement('canvas');
        sourceCanvas.width = canvas.width;
        sourceCanvas.height = canvas.height;
        const sCtx = sourceCanvas.getContext('2d');
        sCtx.drawImage(canvas, 0, 0);

        if (flipY) {
            const flipped = flipCanvasVertical(sourceCanvas);
            sCtx.clearRect(0, 0, sourceCanvas.width, sourceCanvas.height);
            sCtx.drawImage(flipped, 0, 0);
        }

        // Aplicar sangrado de color y purificación inteligente según el modo y XML
        const bleedAlpha = options.bleedAlpha !== undefined ? options.bleedAlpha : true;
        let purifyReport = null;
        if (bleedAlpha && (mode === 'safe' || mode === 'normal')) {
            purifyReport = bleedTransparentPixels(sourceCanvas, 4);
        } else if (bleedAlpha) {
            purifyReport = purifyCanvas(sourceCanvas, {
                mode: mode,
                xmlFrames: options.xmlFrames || null,
                bleedPasses: mode === 'advanced' ? 8 : (mode === 'normal' ? 3 : 5)
            });
        }

        const width = sourceCanvas.width;
        const height = sourceCanvas.height;
        const ctx = sourceCanvas.getContext('2d');
        const imgData = ctx.getImageData(0, 0, width, height);
        const rgba = new Uint8Array(imgData.data.buffer);

        const encoder = await getEncoderModule();

        const rawImage = {
            dimX: width,
            dimY: height,
            dimZ: 1,
            dataType: 0, // U8
            data: rgba
        };

        // ASTCENC_FLG_USE_ALPHA_WEIGHT = (1 << 2) = 4
        // Pondera el error RGB según el nivel de opacidad (alpha), eliminando artefactos en bordes transparentes.
        const flags = options.flags !== undefined ? options.flags : 4;

        const rawConfig = {
            profile: 1, // ASTCENC_PRF_LDR (lineal, igual que astcenc -cl; el juego sube la textura como RGBA lineal)
            flags: flags,
            blockX: blockX,
            blockY: blockY,
            blockZ: 1,
            quality: quality
        };
        // Peso del canal alfa = 8 (equivale a "astcenc -cw 1 1 1 8"): el codificador cuida mucho más
        // la transparencia, reduciendo residuos alrededor del personaje y huecos en zonas opacas.
        // Medido con soul.png en 8x8: residuos visibles 952 -> 628 y huecos 486 -> 165.
        rawConfig.cwAWeight = 8;
        // Opciones avanzadas de astcenc (equivalentes a -cw, -a y -tune... de la herramienta oficial de Arm)
        if (options.astcencConfig) Object.assign(rawConfig, options.astcencConfig);

        const rawSwizzle = {
            r: 0,
            g: 1,
            b: 2,
            a: 3
        };

        const hasThreading = typeof SharedArrayBuffer !== 'undefined' && typeof Atomics !== 'undefined';
        const threads = hasThreading ? Math.max(1, (typeof navigator !== 'undefined' && navigator.hardwareConcurrency) || 2) : 1;
        let payload = new Uint8Array(encoder.compressImage(rawImage, rawConfig, rawSwizzle, threads));

        // Pulido de bordes: recomprime los bloques que dejaron residuos alrededor del personaje
        let repairReport = null;
        if (options.repair !== false) {
            const fixed = repairEdgeBlocks(payload, rgba, width, height, blockX, blockY, encoder, rawConfig, rawSwizzle);
            payload = fixed.payload;
            repairReport = fixed.report;
        }

        // Generar cabecera oficial de 16 bytes
        const header = new Uint8Array(16);
        header[0] = 0x13;
        header[1] = 0xAB;
        header[2] = 0xA1;
        header[3] = 0x5C;
        header[4] = blockX;
        header[5] = blockY;
        header[6] = 1; // blockZ
        header[7] = width & 0xFF;
        header[8] = (width >> 8) & 0xFF;
        header[9] = (width >> 16) & 0xFF;
        header[10] = height & 0xFF;
        header[11] = (height >> 8) & 0xFF;
        header[12] = (height >> 16) & 0xFF;
        header[13] = 1; // dimZ
        header[14] = 0;
        header[15] = 0;

        const astcBytes = new Uint8Array(16 + payload.length);
        astcBytes.set(header, 0);
        astcBytes.set(payload, 16);

        return {
            astcBytes,
            width,
            height,
            blockX,
            blockY,
            bpp: (128 / (blockX * blockY)).toFixed(2),
            payloadLength: payload.length,
            totalLength: astcBytes.length,
            purifyReport,
            repairReport,
            sourceCanvas
        };
    }

    const ASTCEngine = {
        parseHeader,
        decodeAstc,
        astcToCanvas,
        encodeCanvasToAstc,
        flipCanvasVertical,
        flipCanvasHorizontal,
        applyColorBleedAndCleanAlpha,
        bleedTransparentPixels,
        packAtlas,
        renderPackedAtlas,
        DECODER_OUTPUT_FLIPPED,
        purifyCanvas,
        auditTexture,
        initDecoderSync,
        bppForBlock: (bx, by) => (128 / (bx * by)).toFixed(2),
        BLOCK_PRESETS: [
            { name: '4x4', bx: 4, by: 4, bpp: '8.00', desc: 'Máxima Calidad (Texturas principales)' },
            { name: '5x5', bx: 5, by: 5, bpp: '5.12', desc: 'Muy Alta Calidad' },
            { name: '6x6', bx: 6, by: 6, bpp: '3.56', desc: 'Estándar Recomendado FNF Android' },
            { name: '8x8', bx: 8, by: 8, bpp: '2.00', desc: 'Alta Compresión (Ahorro de RAM)' },
            { name: '10x10', bx: 10, by: 10, bpp: '1.28', desc: 'Ultra Compacto (Fondos/Efectos)' },
            { name: '12x12', bx: 12, by: 12, bpp: '0.89', desc: 'Peso Mínimo Extremo (Gama Baja)' }
        ]
    };

    global.ASTCEngine = ASTCEngine;
})(typeof window !== 'undefined' ? window : this);
